const input = $input.first().json || {};

function makeErrorId(source = {}) {
  const eventId = source.event_id || "unknown_event";
  const component = source.component_id || "unknown_component";
  const suffix = Date.now().toString(36);
  return `err_${component}_${eventId}_${suffix}`.replace(/[^a-zA-Z0-9_]/g, "_");
}

function safe(value) {
  return value === undefined || value === null || value === "" ? "-" : String(value);
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C6-G",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        error_log: {
          error_id: null,
          status: "failed",
          severity: null,
          retry_status: null,
          source_component: input.input?.component_id || null,
          source_error_code: input.input?.error?.code || null,
          owner_email: input.config?.error_owner_email || null
        },
        source_result: input.input || {},
        notification_payload: null,
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== false) {
  return fail({
    code: "SOURCE_NOT_FAILED",
    message: "C6-G only creates error log records for failed upstream outputs.",
    details: [{ source_success: source.success }]
  });
}

if (!source.error || typeof source.error !== "object") {
  return fail({
    code: "MISSING_SOURCE_ERROR",
    message: "Failed source output must include an error object."
  });
}

if (!source.error.code) {
  return fail({
    code: "MISSING_SOURCE_ERROR_CODE",
    message: "source.error.code is required."
  });
}

const severityRules = config.severity_rules || {};
const sourceErrorCode = source.error.code;
const severity = severityRules[sourceErrorCode] || config.default_severity || "medium";
const retryStatus = config.default_retry_status || "pending_manual_review";
const ownerEmail = config.error_owner_email || null;
const errorId = makeErrorId(source);
const createdAt = new Date().toISOString();

const errorSummary = [
  `Automation error logged`,
  ``,
  `Error ID: ${errorId}`,
  `Severity: ${severity}`,
  `Retry Status: ${retryStatus}`,
  `Event ID: ${safe(source.event_id)}`,
  `Event Type: ${safe(source.event_type)}`,
  `Source Component: ${safe(source.component_id)}`,
  `Source Error Code: ${safe(sourceErrorCode)}`,
  `Source Error Message: ${safe(source.error.message)}`,
  ``,
  `Next manual action: Review payload, fix configuration/data issue, then mark retry_status as retry_ready or resolved.`
].join("\n");

return [
  {
    json: {
      success: true,
      component_id: "C6-G",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      error_log: {
        error_id: errorId,
        status: "logged",
        severity,
        retry_status: retryStatus,
        source_component: source.component_id || null,
        source_component_version: source.component_version || null,
        source_error_code: sourceErrorCode,
        source_error_message: source.error.message || null,
        source_error_details: source.error.details || [],
        owner_email: ownerEmail,
        created_at: createdAt,
        resolution_status: "open",
        retry_attempts: 0,
        manual_notes: ""
      },
      source_result: source,
      notification_payload: ownerEmail
        ? {
            channel: "email",
            to: ownerEmail,
            subject: `Automation error: ${sourceErrorCode}`,
            text: errorSummary
          }
        : null,
      error: null,
      next_action: config.default_next_action || "notify_error_owner"
    }
  }
];
